CREATE TABLE noten_alt (
  schueler_id INTEGER,
  fach VARCHAR(5),
  note INTEGER
);

INSERT INTO noten_alt
  (schueler_id, fach, note)
SELECT schueler_id, fach, note
FROM noten;
-- OK (14 Zeilen)

BEGIN;
UPDATE noten SET note = 1;
-- OK (14 Zeilen)
-- Hoppla, WHERE vergessen!
ROLLBACK;

SELECT COUNT(*) FROM noten
WHERE note = 1;
-- 3
